previewCss:
.darma-loader-darma-b16-morse-code-blink { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #fde047); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .3); position: relative; display: flex; gap: 3%; align-items: center; }
.darma-loader-darma-b16-morse-code-blink span { flex: none; height: 34%; border-radius: 4px; background: color-mix(in srgb, var(--accent) 22%, transparent); animation: darma-loader-darma-b16-morse-code-blink-morse-key calc(var(--loader-speed, 1s) * 3) steps(1, end) infinite; }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(1) { width: 7%; }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(2) { width: 18%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(3) { width: 7%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(4) { width: 7%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(5) { width: 18%; animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
.darma-loader-darma-b16-morse-code-blink span:nth-of-type(6) { width: 18%; animation-delay: calc(var(--loader-speed, 1s) * 2); }
.darma-loader-darma-b16-morse-code-blink .darma-loader-darma-b16-morse-code-blink__lamp { position: absolute; right: 0; top: 16%; width: 9%; height: 62%; border-radius: 50%; background: var(--accent-2); opacity: .2; animation: darma-loader-darma-b16-morse-code-blink-morse-lamp calc(var(--loader-speed, 1s) * .5) steps(1, end) infinite; }
@keyframes darma-loader-darma-b16-morse-code-blink-morse-key { 0%, 4% { background: color-mix(in srgb, var(--accent) 20%, transparent); transform: scaleY(1); } 6%, 22% { background: var(--accent); transform: scaleY(1.5); } 26%, 100% { background: color-mix(in srgb, var(--accent) 20%, transparent); transform: scaleY(1); } }
@keyframes darma-loader-darma-b16-morse-code-blink-morse-lamp { 0%, 49% { opacity: 1; box-shadow: 0 0 12px var(--accent-2); } 50%, 100% { opacity: .18; box-shadow: none; } }

